直接用 strlen 求字符串长度输出。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char s[105];
    cin >> s;
    cout << strlen(s) << endl;
    return 0;
}
```

用 strcat(a, b) 将 b 拼接到 a 末尾，再输出 a。a 需开足够大的空间（如 205）。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char a[205], b[105];
    cin >> a >> b;
    strcat(a, b);
    cout << a << endl;
    return 0;
}
```

遍历字符串，若字符是小写字母则 ASCII 码减 32 转成大写，然后输出。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char s[105];
    cin >> s;
    for (int i = 0; s[i] != '\0'; i++)
        if (s[i] >= 'a' && s[i] <= 'z') s[i] -= 32;
    cout << s << endl;
    return 0;
}
```

调用 strcmp(a, b) 得返回值 t，按 t 的正负零分别输出 -1、1、0。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char a[105], b[105];
    cin >> a >> b;
    int t = strcmp(a, b);
    if (t < 0) cout << -1 << endl;
    else if (t > 0) cout << 1 << endl;
    else cout << 0 << endl;
    return 0;
}
```

strcmp(a, b) == 0 时输出 SAME，否则输出 DIFFERENT。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char a[105], b[105];
    cin >> a >> b;
    if (strcmp(a, b) == 0) cout << "SAME" << endl;
    else cout << "DIFFERENT" << endl;
    return 0;
}
```
